package dev.daweapon.type.catacombs.engine;

import dev.daweapon.dungeons.catacombs.layout.DoorType;
import dev.daweapon.type.catacombs.engine.look.Skin;

public enum KeyType {
    WITHER("Wither Key", "<8>", DoorType.WITHER,
            ""),
    BLOOD("Blood Key", "<c>", DoorType.BLOOD,
            "");

    private final String displayName;
    private final String colour;
    private final DoorType door;
    private final Skin head;

    KeyType(String displayName, String colour, DoorType door, String headTexture) {
        this.displayName = displayName;
        this.colour = colour;
        this.door = door;
        this.head = new Skin(headTexture, null);
    }

    public String displayName() {
        return displayName;
    }

    public String coloured() {
        return colour + displayName;
    }

    public DoorType door() {
        return door;
    }

    public Skin head() {
        return head;
    }
}
